import '../../features/privacy/domain/privacy_checklist.dart';

/// Spanish privacy self-audit guidance keyed by stable practice IDs.
class SpanishPrivacyContent {
  SpanishPrivacyContent._();

  static const Map<String, Map<String, String>> _practices = {
    'account-unique-passwords': {'title':'Utiliza contraseñas únicas para tus cuentas importantes','why':'Reutilizar una contraseña significa que una filtración en un servicio también puede poner en riesgo tus otras cuentas.','action':'Utiliza un gestor de contraseñas fiable para crear una contraseña larga y diferente para cada cuenta importante. Protege el gestor con una contraseña maestra robusta y configura las opciones de recuperación disponibles.','limit':'Un gestor de contraseñas no puede proteger una cuenta si la contraseña maestra o el canal de recuperación están comprometidos.'},
    'account-mfa': {'title':'Activa la autenticación multifactor','why':'Un segundo factor puede reducir las consecuencias del robo de una contraseña.','action':'Activa MFA en tus cuentas de correo, finanzas, nube y redes sociales. Cuando sea posible, prioriza las llaves de acceso o las llaves de seguridad y protege las copias de seguridad de tu aplicación de autenticación.','limit':'Los métodos MFA ofrecen distintos niveles de seguridad. Los códigos SMS pueden estar expuestos a ataques de intercambio de SIM o portabilidad fraudulenta.'},
    'account-recovery': {'title':'Revisa las opciones de recuperación de tus cuentas','why':'Una dirección de correo o un número de recuperación obsoleto puede impedir una recuperación legítima o facilitar la toma de control de una cuenta.','action':'Revisa las direcciones de recuperación, números de teléfono, códigos de respaldo y dispositivos de confianza en la configuración oficial de seguridad de cada servicio.','limit':'La configuración de recuperación depende de cada servicio. ORVIKA no puede verificar que un proveedor haya aplicado los cambios.'},
    'device-updates': {'title':'Mantén actualizados los sistemas y las aplicaciones','why':'Las actualizaciones suelen corregir vulnerabilidades que, de otro modo, podrían aprovechar los atacantes.','action':'Activa las actualizaciones de seguridad automáticas cuando sea posible. Instala las actualizaciones mediante la herramienta integrada del dispositivo o la tienda oficial.','limit':'Una actualización reduce los riesgos conocidos, pero no garantiza que un dispositivo esté libre de amenazas.'},
    'device-lock': {'title':'Protege tu dispositivo con un bloqueo de pantalla robusto','why':'Un dispositivo perdido o desatendido y desbloqueado puede exponer mensajes, cuentas y datos almacenados.','action':'Utiliza un PIN o contraseña largos, establece un intervalo breve de bloqueo automático y configura la biometría como método adicional y práctico de desbloqueo.','limit':'Las opciones biométricas y de bloqueo varían según el dispositivo. El bloqueo de pantalla no cifra necesariamente todas las copias de seguridad externas.'},
    'device-backups': {'title':'Revisa las copias de seguridad y las opciones de localización','why':'Las copias de seguridad facilitan la recuperación, mientras que las funciones de localización pueden ayudar a encontrar o proteger a distancia un dispositivo perdido.','action':'Comprueba qué datos se respaldan, quién puede acceder a la cuenta de respaldo, si existe cifrado de copias de seguridad y si están activadas la localización y el bloqueo remoto.','limit':'La disponibilidad y el cifrado predeterminado varían según el sistema operativo y el proveedor. Consulta la documentación actual del proveedor.'},
    'apps-permissions': {'title':'Revisa los permisos de las aplicaciones','why':'Las aplicaciones pueden conservar acceso a la ubicación, contactos, cámara, micrófono, fotos o dispositivos cercanos más allá de lo necesario.','action':'Abre la configuración de privacidad o permisos de aplicaciones del sistema. Elimina accesos innecesarios y, si es posible, prefiere el acceso puntual o solo mientras se usa la aplicación.','limit':'Los nombres y controles de permisos varían según el sistema y su versión. ORVIKA no lee ni modifica estos permisos.'},
    'apps-unused': {'title':'Elimina las aplicaciones que ya no utilizas','why':'Las aplicaciones sin uso pueden conservar sesiones abiertas, almacenar datos o seguir recibiendo actualizaciones y permisos.','action':'Desinstala las aplicaciones que ya no necesites. Antes de eliminarlas, exporta la información necesaria y, cuando corresponda, revoca el acceso a las cuentas vinculadas.','limit':'Desinstalar una aplicación no elimina necesariamente los datos que su proveedor ya conserva.'},
    'apps-sources': {'title':'Instala aplicaciones desde fuentes fiables','why':'Los instaladores no verificados y las aplicaciones modificadas pueden contener código no deseado o solicitar accesos excesivos.','action':'Utiliza tiendas oficiales o el canal de distribución verificado del editor. Antes de instalar, comprueba el desarrollador, los permisos solicitados y el historial de actualizaciones.','limit':'Que una aplicación esté en una tienda oficial no garantiza que sea segura ni respetuosa con la privacidad.'},
    'browsing-tracking': {'title':'Revisa la privacidad y el seguimiento del navegador','why':'Las cookies, los permisos de sitios y el seguimiento entre sitios pueden revelar tus hábitos de navegación.','action':'Revisa la protección contra el seguimiento, las cookies de terceros, los permisos de sitios guardados y las extensiones. Elimina las extensiones que no reconozcas o necesites.','limit':'Bloquear rastreadores puede afectar al funcionamiento de algunos sitios y no hace que la navegación sea anónima.'},
    'browsing-sharing': {'title':'Limita la información personal que compartes públicamente','why':'Las publicaciones públicas y los datos del perfil pueden combinarse para facilitar la suplantación de identidad, las estafas dirigidas o los ataques de recuperación de cuentas.','action':'Revisa los campos públicos de tu perfil, la audiencia de las publicaciones, el uso compartido de ubicación y las publicaciones antiguas. Evita publicar documentos de identidad, planes de viaje o pistas de recuperación de cuentas.','limit':'El contenido puede copiarse o archivarse antes de que cambies la configuración de privacidad.'},
    'browsing-network': {'title':'Utiliza conexiones fiables y verifica las solicitudes de red','why':'Los portales Wi-Fi falsos y las conexiones no protegidas pueden exponer tu actividad o redirigirte a páginas engañosas.','action':'Prioriza redes de confianza, verifica el nombre de la red con su responsable, evita operaciones sensibles en redes desconocidas y utiliza sitios HTTPS. Desactiva la conexión automática a puntos de acceso desconocidos.','limit':'HTTPS protege los datos durante su transmisión al sitio, pero no demuestra que este sea legítimo ni convierte una red desconocida en fiable.'},
  };

  static PrivacyPractice localize(PrivacyPractice practice, String languageCode) {
    if (languageCode != 'es') return practice;
    final values = _practices[practice.id];
    if (values == null) return practice;
    return PrivacyPractice(id: practice.id, title: values['title']!, category: practice.category,
      why: values['why']!, action: values['action']!, limit: values['limit']!);
  }
}
